import itertools

def check_colorful(m, n, d):
    # Use a recursive search with pruning
    def backtrack(current_seq):
        if len(current_seq) == m:
            for i in range(m):
                window = [current_seq[(i + j) % m] for j in range(n)]
                if len(set(window)) < d:
                    return False
            return True

        for flavor in range(d):
            current_seq.append(flavor)
            if len(current_seq) >= n:
                window = current_seq[-n:]
                if len(set(window)) < d:
                    current_seq.pop()
                    continue
            if backtrack(current_seq):
                return True
            current_seq.pop()
        return False

    return backtrack([])

