for m in range(4, 15):
    print(f"m={m}: {check_colorful(m, 4, 3)}")

import itertools

def check_all(m, n, d):
    for p in itertools.product(range(d), repeat=m):
        valid = True
        for i in range(m):
            window = [p[(i + j) % m] for j in range(n)]
            if len(set(window)) < d:
                valid = False
                break
        if valid:
            return True
    return False

for m in range(4, 10):
    print(f"m={m}: {check_all(m, 4, 3)}")

